import unittest

def is_even(number):
    return number % 2 == 0

class TestEven(unittest.TestCase):
    def test_zero(self):
        self.assertTrue(is_even(0))

    def test_positive_even(self):
        self.assertEqual(is_even(4), True)

    def test_odd(self):
        self.assertFalse(is_even(3))

