import datetime

def days_until_sunday(date_text):
    day = datetime.datetime.strptime(date_text, "%Y-%m-%d")
    return 6 - day.weekday()

import random

def assign_rooms(count, rng):
    if not 0 <= count <= 50:
        raise ValueError("Count must be between 0 and 50")
    return rng.sample(range(1, 51), count)

